function medianOfTwo(a: number[], b: number[]): number {
  const total = a.length + b.length;
  let i = 0, j = 0, prev = 0, cur = 0;
  for (let k = 0; k <= Math.floor(total / 2); k++) {
    prev = cur;
    if (j >= b.length || (i < a.length && a[i] <= b[j])) cur = a[i++];
    else cur = b[j++];
  }
  return total % 2 === 1 ? cur : (prev + cur) / 2;
}

