function medianOfTwo(a: number[], b: number[]): number {
  if (a.length > b.length) [a, b] = [b, a]; // search the shorter list
  const m = a.length, n = b.length;
  const half = (m + n + 1) >> 1; // left part gets the extra item when the total is odd
  let lo = 0, hi = m; // i items of a go left; i = m is allowed
  while (lo <= hi) {
    const i = (lo + hi) >> 1, j = half - i;
    const aLeft = i > 0 ? a[i - 1] : -Infinity, aRight = i < m ? a[i] : Infinity;
    const bLeft = j > 0 ? b[j - 1] : -Infinity, bRight = j < n ? b[j] : Infinity;
    if (aLeft > bRight) hi = i - 1; // too much of a on the left
    else if (bLeft > aRight) lo = i + 1; // too little of a on the left
    else {
      const leftMax = Math.max(aLeft, bLeft);
      if ((m + n) % 2 === 1) return leftMax;
      return (leftMax + Math.min(aRight, bRight)) / 2;
    }
  }
  throw new Error("inputs were not sorted");
}

